@Service
public class TicketBookingService {

    private final SeatRepository seatRepository;
    private final RedissonClient redissonClient;

    public TicketBookingService(SeatRepository seatRepository, RedissonClient redissonClient) {
        this.seatRepository = seatRepository;
        this.redissonClient = redissonClient;
    }

    @Transactional
    public boolean bookSeat(Long showId, Long seatId, Long userId) {
        String lockKey = "lock:show:" + showId + ":seat:" + seatId;
        RLock lock = redissonClient.getLock(lockKey);

        try {
            // Attempt to acquire lock within 3 seconds, hold for up to 10 seconds
            boolean isLocked = lock.tryLock(3, 10, TimeUnit.SECONDS);
            if (!isLocked) {
                throw new SeatContentionException("Seat is currently being booked by another user.");
            }

            Seat seat = seatRepository.findByIdAndShowId(seatId, showId)
                .orElseThrow(() -> new EntityNotFoundException("Seat not found"));

            if (seat.getStatus() != SeatStatus.AVAILABLE) {
                return false; // Already booked or locked
            }

            seat.setStatus(SeatStatus.LOCKED);
            seat.setLockedByUserId(userId);
            seat.setLockExpirationTime(Instant.now().plusSeconds(300));
            seatRepository.save(seat);

            return true;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new BookingProcessingException("Booking interrupted", e);
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }
}
